contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 1000",
      "description": "The number of test cases T is between 1 and 1000."
    },
    {
      "id": "P2",
      "expression": "all(1 <= N <= 10**5 for N in [int(line.split()[0]) for line in stdin.splitlines()[1::4]])",
      "description": "For each test case, the length of arrays A and P, N, is between 1 and 100,000."
    },
    {
      "id": "P3",
      "expression": "all(len(line.split()) == N for line, N in zip(stdin.splitlines()[2::4], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, the length of array A is N."
    },
    {
      "id": "P4",
      "expression": "all(len(line.split()) == N for line, N in zip(stdin.splitlines()[3::4], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, the length of array P is N."
    },
    {
      "id": "P5",
      "expression": "all(set(map(int, line.split())) == set(range(1, N+1)) for line, N in zip(stdin.splitlines()[2::4], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, array A is a permutation of integers from 1 to N."
    },
    {
      "id": "P6",
      "expression": "all(set(map(int, line.split())) == set(range(1, N+1)) for line, N in zip(stdin.splitlines()[3::4], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, array P is a permutation of integers from 1 to N."
    },
    {
      "id": "P7",
      "expression": "all(1 <= Q <= 10**5 for Q in [int(line.split()[0]) for line in stdin.splitlines()[4::4]])",
      "description": "For each test case, the number of operations Q is between 1 and 100,000."
    },
    {
      "id": "P8",
      "expression": "all(all(1 <= int(op.split()[0]) <= 3 for op in operations) for operations in [stdin.splitlines()[5+i*4:5+i*4+Q] for i, Q in enumerate([int(line.split()[0]) for line in stdin.splitlines()[4::4]])])",
      "description": "For each test case, each operation is of type 1, 2, or 3."
    },
    {
      "id": "P9",
      "expression": "all(all(1 <= int(op.split()[1]) <= N and 1 <= int(op.split()[2]) <= N and int(op.split()[1]) != int(op.split()[2]) for op in operations if op.split()[0] == '2') for operations, N in zip([stdin.splitlines()[5+i*4:5+i*4+Q] for i, Q in enumerate([int(line.split()[0]) for line in stdin.splitlines()[4::4]])], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, in operations of type 2, x and y are distinct integers between 1 and N."
    },
    {
      "id": "P10",
      "expression": "all(all(1 <= int(op.split()[1]) <= N for op in operations if op.split()[0] == '3') for operations, N in zip([stdin.splitlines()[5+i*4:5+i*4+Q] for i, Q in enumerate([int(line.split()[0]) for line in stdin.splitlines()[4::4]])], [int(line.split()[0]) for line in stdin.splitlines()[1::4]]))",
      "description": "For each test case, in operations of type 3, x is an integer between 1 and N."
    }
  ],
